insert into public.courses (slug, title, subject, credits, focus)
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Beginnings: Creation and the Fall$j$, $j${"readings": [{"title": "Genesis 1 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Genesis%201&version=KJV"}, {"title": "Genesis 2 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Genesis%202&version=KJV"}, {"title": "Genesis 3 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Genesis%203&version=KJV"}], "body": "Read Genesis 1, 2 and 3 in the King James Version. Then read this lesson.\n\nGenesis means beginnings. Chapter 1 shows God creating the heaven and the earth in an ordered way over six days and resting on the seventh. Chapter 2 tells the story again with close attention to the making of man and woman and the garden in Eden. Chapter 3 records the fall: the serpent tempts the woman, both eat of the tree God had forbidden, and sin enters the world. Yet in Genesis 3:15 God speaks the first promise of a coming deliverer.\n\nKey words: creation, covenant, fall, sin, promise.\n\nYour task: (1) List the six days of creation in order. (2) Name the one command God gave Adam about the garden (Genesis 2:16 and 17). (3) Write the promise of Genesis 3:15 in your own words.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome to Old Testament Survey. Over this course we will walk through the whole Old Testament, one story at a time, and we will read every word of it in the King James Version. Today we begin where the Bible begins.\n\nThe very first verse says, In the beginning God created the heaven and the earth. Notice what the Bible does not do. It does not try to prove that God exists. It simply starts with God, already there, already working. Everything else in Scripture rests on that opening line.\n\nThe first chapter of Genesis moves in an orderly pattern. Light on the first day. The sky on the second. Dry land and plants on the third. Sun, moon and stars on the fourth. Fish and birds on the fifth. Land animals and then man on the sixth. Notice the order and the care. God made a world that was ready for the people He would place in it. Scripture says in Genesis 1:27, So God created man in his own image, in the image of God created he him; male and female created he them. Human beings are not accidents. We were made with purpose and with worth.\n\nChapter 2 slows down and shows us the garden in Eden. God gave Adam work to do, and He gave one command. Of every tree in the garden Adam could freely eat, but of the tree of the knowledge of good and evil he was not to eat. That one command was a test of trust.\n\nThen comes chapter 3, the saddest chapter in the opening of the Bible. The serpent questions what God said. The woman and then Adam eat of the forbidden tree. Sin enters, and with it shame, fear and separation from God. We call this the fall, and it explains why the world we know is so broken.\n\nBut listen to what God says next. In Genesis 3:15 He speaks to the serpent of a coming seed of the woman who will bruise his head. That is the first promise of a deliverer. Even in the moment of failure, God was already pointing toward rescue. As you read this week, watch for that promise to grow.\n\nYour task is to list the six days of creation, name God's one command to Adam, and put Genesis 3:15 in your own words. Then take the four question check.\n\nRemember, every great story has a beginning, and every great life begins with trusting God. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Beginnings: Creation and the Fall$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Promise: Abraham and the Covenant$j$, $j${"readings": [{"title": "Genesis 12 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Genesis%2012&version=KJV"}, {"title": "Genesis 15 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Genesis%2015&version=KJV"}, {"title": "Genesis 22 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Genesis%2022&version=KJV"}, {"title": "Genesis 50 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Genesis%2050&version=KJV"}], "body": "Read Genesis 12, 15 and 22 and Genesis 50:15 to 21 in the King James Version. Then read this lesson.\n\nAfter the fall, sin spread, and God dealt with the world through the flood and then through the scattering at Babel. In Genesis 12 God turned to one man. He called Abram to leave his country and promised to make of him a great nation, to bless him, and to bless all the families of the earth through him. God later changed his name to Abraham. His faith is summarized in Genesis 15:6, and his greatest test came on Mount Moriah in Genesis 22.\n\nThe promise passed to his son Isaac, then to Jacob, whom God renamed Israel. Jacob had twelve sons. One of them, Joseph, was sold into Egypt by his brothers, rose to rule under Pharaoh, and later saved his family from famine. Genesis ends with Israel living in Egypt.\n\nKey words: covenant, promise, faith, righteousness, tribe.\n\nYour task: (1) List the three parts of God's promise to Abram in Genesis 12:1 to 3. (2) Say in your own words what Genesis 15:6 teaches about faith. (3) Explain what Joseph meant in Genesis 50:20.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Last lesson we saw sin enter the world. Today we see how God began to answer it, and the answer starts with one man and one promise.\n\nAfter the fall, things got worse. By Genesis chapter 6, the earth was filled with violence, and God sent the flood. After the flood, people gathered at Babel and tried to build their own way to heaven, and God scattered them. Then, in Genesis chapter 12, God did something new. He spoke to one man named Abram.\n\nScripture says, Now the LORD had said unto Abram, Get thee out of thy country, and from thy kindred, and from thy father's house, unto a land that I will shew thee: And I will make of thee a great nation, and I will bless thee, and make thy name great; and thou shalt be a blessing: And I will bless them that bless thee, and curse him that curseth thee: and in thee shall all families of the earth be blessed. Listen for three promises there. A land. A great nation. And a blessing that would reach every family on earth.\n\nAbram did not know the way, but he went. Years later, with no child in his tent, he believed God's promise of descendants like the stars. Genesis 15:6 says, And he believed in the LORD; and he counted it to him for righteousness. That verse is one of the most important in the Old Testament. It tells us that trusting God is the foundation of a right relationship with Him.\n\nGod changed his name to Abraham and gave him a son, Isaac, in his old age. In Genesis 22, God tested Abraham on Mount Moriah, and Abraham showed that he trusted God above everything he loved. The promise then passed from Isaac to Jacob, whom God renamed Israel, and Jacob had twelve sons.\n\nOne of those sons was Joseph. His brothers sold him into Egypt, yet God raised him up to save the family from famine. Years later he told those same brothers, in Genesis 50:20, But as for you, ye thought evil against me; but God meant it unto good, to bring to pass, as it is this day, to save much people alive.\n\nThat is the lesson. People may mean evil, but God is working out His promise. Your task is to list the three parts of the promise, explain Genesis 15:6, and explain what Joseph meant. Then take the four question check.\n\nFaith waits for God's timing. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Promise: Abraham and the Covenant$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Deliverance: Exodus and Sinai$j$, $j${"readings": [{"title": "Exodus 3 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Exodus%203&version=KJV"}, {"title": "Exodus 12 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Exodus%2012&version=KJV"}, {"title": "Exodus 14 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Exodus%2014&version=KJV"}, {"title": "Exodus 20 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Exodus%2020&version=KJV"}], "body": "Read Exodus 3, 12, 14 and 20 in the King James Version. Then read this lesson.\n\nExodus means a way out. The family of Jacob grew into a nation in Egypt, and a later Pharaoh made them slaves. God heard their cry and called Moses at the burning bush, where He revealed His name in Exodus 3:14. Through ten plagues God showed that He was greater than the gods of Egypt. On the last night each Israelite household put the blood of a lamb on its doorposts, and the destroyer passed over them. That night is called the Passover. God then opened the Red Sea and brought Israel through on dry ground.\n\nAt Mount Sinai God made a covenant with the nation and gave the Ten Commandments in Exodus 20. They begin with God's own rescue, then call Israel to worship Him alone.\n\nKey words: Passover, deliverance, covenant, commandments, Sinai.\n\nYour task: (1) Tell the Passover story in four sentences. (2) Name the sea Israel crossed and the mountain where the commandments were given. (3) Write the first commandment from Exodus 20:3.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "When Genesis ends, the family of Jacob is safe in Egypt. When Exodus begins, they are slaves. This is the book of the great rescue, and it shapes the rest of the Bible.\n\nExodus 12:40 tells us the people lived in Egypt for four hundred and thirty years. They grew from one family into a nation, and a new Pharaoh who did not remember Joseph made them work in bondage. They cried out, and God heard.\n\nGod called Moses at a bush that burned and was not consumed. When Moses asked who he should say had sent him, God answered, I AM THAT I AM. God is the one who is, the self existing and unchanging God. He sent Moses to Pharaoh with a message, Let my people go.\n\nPharaoh refused, and God sent ten plagues. Each one showed that the LORD was greater than the gods of Egypt. The last plague was the death of the firstborn, and God gave Israel a way of protection. Each household was to put the blood of a lamb on the doorposts. God said in Exodus 12:13, And the blood shall be to you for a token upon the houses where ye are: and when I see the blood, I will pass over you. That is why we call that night the Passover. Israel still remembers it every year.\n\nPharaoh let the people go, then chased them. At the Red Sea God opened a path through the water, and Israel crossed on dry ground. The sea closed on Pharaoh's army.\n\nThree months later, Israel came to Mount Sinai, and God made a covenant with the nation. He gave the Ten Commandments in Exodus chapter 20. Notice how they begin. I am the LORD thy God, which have brought thee out of the land of Egypt, out of the house of bondage. Thou shalt have no other gods before me. God starts with who He is and what He has done, and then He tells His people how to live.\n\nYour task is to tell the Passover story, name the sea and the mountain, and write the first commandment. Then take the four question check.\n\nGod hears the cry of His people. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Deliverance: Exodus and Sinai$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Holiness and the Wilderness: Leviticus, Numbers and Deuteronomy$j$, $j${"readings": [{"title": "Leviticus 19 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Leviticus%2019&version=KJV"}, {"title": "Numbers 6 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Numbers%206&version=KJV"}, {"title": "Deuteronomy 6 (King James Version)", "url": "https://www.biblegateway.com/passage/?search=Deuteronomy%206&version=KJV"}], "body": "Read Leviticus 19:1 to 4, Numbers 6:22 to 27 and Deuteronomy 6:1 to 9 in the King James Version. Then read this lesson.\n\nAfter Sinai, Israel built the tabernacle, the tent where God's presence dwelt among them. Leviticus is the book of worship and holiness. It explains the offerings, the work of the priests, the Day of Atonement and the feasts, and it repeats the call to be a holy people. Numbers records the counting of the tribes and the long journey toward the promised land. When Israel refused to trust God at the border, that generation wandered in the wilderness for forty years. Deuteronomy means second law. It records Moses' farewell sermons to the new generation, calling them to love the LORD with all their heart. Moses saw the land from Mount Nebo and died, and Joshua took his place.\n\nThe first five books of the Bible are called the Law, or the Pentateuch.\n\nKey words: tabernacle, priest, holy, atonement, wilderness.\n\nYour task: (1) Say why Israel wandered forty years. (2) Write Deuteronomy 6:5 from memory or from your Bible. (3) Name the five books of the Law in order.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "We are ending our first unit, the five books of the Law. Today we cover the last three: Leviticus, Numbers and Deuteronomy.\n\nAfter the great rescue and the covenant at Sinai, God gave Moses a pattern for a tent called the tabernacle. It was the place where God's presence dwelt among His people. Leviticus is the handbook for that worship. It describes the offerings, the work of the priests from the family of Aaron, and the Day of Atonement, when sin was dealt with once a year. Leviticus 19:2 gives the heart of the book, Ye shall be holy: for I the LORD your God am holy. Holy means set apart for God. Israel was to live differently from the nations around them.\n\nNumbers begins with a census, a counting of the tribes, and then the journey toward the promised land. At the border, twelve spies went in. Ten came back afraid and said the people were too strong. Only Caleb and Joshua said God would give them the land. Because Israel refused to trust God, that generation wandered in the wilderness for forty years. Even there, God provided food and water and led them by a cloud by day and fire by night. In Numbers 6 God gave the priests a blessing to speak over His people, The LORD bless thee, and keep thee: The LORD make his face shine upon thee, and be gracious unto thee: The LORD lift up his countenance upon thee, and give thee peace.\n\nDeuteronomy means second law. Forty years later, a new generation stood across the Jordan, and Moses preached his last sermons to them. He reminded them of God's works and called them to obey. The heart of his message is in Deuteronomy 6:4 and 5, Hear, O Israel: The LORD our God is one LORD: And thou shalt love the LORD thy God with all thine heart, and with all thy soul, and with all thy might. Israel still says those words every day.\n\nMoses climbed Mount Nebo and saw the land from a distance, and he died there. Joshua was chosen to lead the people in.\n\nThose five books, Genesis, Exodus, Leviticus, Numbers and Deuteronomy, are called the Law, or the Pentateuch. Your task is to explain the forty years, write Deuteronomy 6:5, and name the five books in order. Then take the four question check and the Unit 1 quiz.\n\nHoliness begins with loving God above all else. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Holiness and the Wilderness: Leviticus, Numbers and Deuteronomy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: The Covenant Thread$j$, $j${"prompt": "Choose one covenant moment from this unit: God's promise to Abram (Genesis 12:1 to 3), the Passover (Exodus 12), or the giving of the commandments (Exodus 20). Write one paragraph of 150 to 200 words. State what God promised or commanded, tell what the people were asked to do in response, and explain one thing the passage shows about the character of God. Quote at least one verse from the King James Version.", "rubric": "Total 100. Accurate summary of what God promised or commanded: 30. Describes the people's response: 20. Shows what the passage reveals about God, with a quoted King James Version verse: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: The Covenant Thread$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Promises Kept$j$, $j${"prompt": "God made promises to Abraham that took generations to fulfill. Think about a time you waited for something promised, or someone who kept a promise to you over a long time. Describe it, and explain what waiting taught you about trust. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Promises Kept$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Beginnings: Creation and the Fall$j$, $j${"questions": [{"q": "What does the word Genesis mean?", "options": ["Judges", "Laws", "Beginnings", "Journeys"]}, {"q": "On which day of creation did God make man?", "options": ["The seventh day", "The sixth day", "The third day", "The fifth day"]}, {"q": "From which tree did God command Adam not to eat?", "options": ["The tree of life", "The tree of the knowledge of good and evil", "Every tree in the garden", "The fig tree"]}, {"q": "Which verse holds the first promise of a coming deliverer?", "options": ["Genesis 1:1", "Genesis 4:1", "Genesis 3:15", "Genesis 2:7"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Beginnings: Creation and the Fall$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,2}'::int[], array[$j$Genesis means beginnings, and it is the book of beginnings.$j$,$j$God made man on the sixth day, as recorded in Genesis 1:26 to 31.$j$,$j$God commanded Adam not to eat of the tree of the knowledge of good and evil (Genesis 2:16 and 17).$j$,$j$Genesis 3:15 speaks of the seed of the woman who would bruise the head of the serpent.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Beginnings: Creation and the Fall$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Promise: Abraham and the Covenant$j$, $j${"questions": [{"q": "What did God tell Abram to do in Genesis 12?", "options": ["Build an ark", "Leave his country and go to a land God would show him", "Build a tower", "Return to Egypt"]}, {"q": "What does Genesis 15:6 say God counted to Abram for righteousness?", "options": ["His sacrifice", "His belief in the LORD", "His wealth", "His obedience to the law"]}, {"q": "Which son of Isaac was renamed Israel?", "options": ["Joseph", "Benjamin", "Esau", "Jacob"]}, {"q": "What did Joseph tell his brothers about their evil act?", "options": ["God meant it unto good", "God would punish them", "He would never forgive them", "It was only an accident"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Promise: Abraham and the Covenant$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,0}'::int[], array[$j$God called Abram to leave his country and go to a land that He would show him.$j$,$j$Genesis 15:6 says that Abram believed in the LORD and that God counted it to him for righteousness.$j$,$j$God renamed Jacob as Israel, and his twelve sons became the tribes of Israel.$j$,$j$In Genesis 50:20 Joseph said that God meant it unto good, to save much people alive.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Promise: Abraham and the Covenant$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Deliverance: Exodus and Sinai$j$, $j${"questions": [{"q": "Who did God call at the burning bush to lead Israel out of Egypt?", "options": ["Moses", "Joseph", "Joshua", "Aaron"]}, {"q": "What is the name of the night when the destroyer passed over the houses marked with blood?", "options": ["Pentecost", "Purim", "Jubilee", "Passover"]}, {"q": "Which sea did Israel cross on dry ground?", "options": ["The Great Sea", "The Red Sea", "The Dead Sea", "The Sea of Galilee"]}, {"q": "Where did God give Israel the Ten Commandments?", "options": ["Mount Moriah", "Mount Carmel", "Mount Nebo", "Mount Sinai"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Deliverance: Exodus and Sinai$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,3}'::int[], array[$j$God called Moses at the burning bush in Exodus 3.$j$,$j$God said, I will pass over you, so the night is called the Passover.$j$,$j$God opened the Red Sea so that Israel crossed on dry ground (Exodus 14).$j$,$j$God gave the Ten Commandments at Mount Sinai (Exodus 19 and 20).$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Deliverance: Exodus and Sinai$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Holiness and the Wilderness: Leviticus, Numbers and Deuteronomy$j$, $j${"questions": [{"q": "Which book gives the most detail about offerings, priests and holiness?", "options": ["Deuteronomy", "Genesis", "Leviticus", "Numbers"]}, {"q": "Why did Israel wander in the wilderness for forty years?", "options": ["They lost the map", "Pharaoh's army blocked them", "They refused to trust God at the border of the land", "They wanted to stay in Egypt"]}, {"q": "Which book contains Moses' farewell sermons and the words of Deuteronomy 6:4 and 5?", "options": ["Deuteronomy", "Leviticus", "Exodus", "Numbers"]}, {"q": "Who led Israel into the promised land after Moses died?", "options": ["Joshua", "Samuel", "Aaron", "Caleb"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Holiness and the Wilderness: Leviticus, Numbers and Deuteronomy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,0,0}'::int[], array[$j$Leviticus is the book of worship, priests, offerings and holiness.$j$,$j$After the spies returned, Israel refused to trust God, so that generation wandered forty years (Numbers 13 and 14).$j$,$j$Deuteronomy records Moses' final sermons, including the call to love the LORD with all the heart.$j$,$j$Joshua was chosen to lead Israel after Moses (Deuteronomy 34:9).$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Holiness and the Wilderness: Leviticus, Numbers and Deuteronomy$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: The Law, Genesis to Deuteronomy$j$, $j${"questions": [{"q": "The first five books of the Bible are called:", "options": ["The Gospels", "The Law", "The Writings", "The Prophets"]}, {"q": "Which of these was part of God's promise to Abram in Genesis 12?", "options": ["A great nation", "A throne in Babylon", "A palace in Egypt", "A kingdom ruled by Pharaoh"]}, {"q": "What does Genesis 3:15 promise?", "options": ["A great tower", "A flood", "A coming deliverer who would bruise the serpent's head", "A new garden"]}, {"q": "What happened on the night of the first Passover?", "options": ["The destroyer passed over houses marked with the blood of a lamb", "Moses received the commandments", "The walls of Jericho fell", "The Red Sea parted"]}, {"q": "Which book repeats the call to be holy because the LORD is holy?", "options": ["Ruth", "Genesis", "Leviticus", "Exodus"]}, {"q": "According to Deuteronomy 6:5, how much of our heart are we to love the LORD with?", "options": ["All of it", "Half of it", "Some of it", "Only on holy days"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: The Law, Genesis to Deuteronomy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,0,2,0}'::int[], array[$j$Genesis through Deuteronomy are called the Law, or the Pentateuch.$j$,$j$God promised Abram a land, a great nation, and a blessing to all families of the earth.$j$,$j$Genesis 3:15 is the first promise of a coming deliverer.$j$,$j$God said, when I see the blood, I will pass over you (Exodus 12:13).$j$,$j$Leviticus 19:2 says, Ye shall be holy: for I the LORD your God am holy.$j$,$j$Deuteronomy 6:5 says to love the LORD thy God with all thine heart, and with all thy soul, and with all thy might.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: The Law, Genesis to Deuteronomy$j$ on conflict (item_id) do nothing;
