-- BIB 101 Old Testament Survey, unit 1. Safe to run more than once.

alter table public.courses add column if not exists video_url text;

values ('bib-101', 'BIB 101 Old Testament Survey', 'Bible', 1.0, $j$BIB 101 is a one credit survey of the Old Testament in the King James Version. Students read the Law, the historical books, the books of poetry and wisdom, and the prophets, learn the setting and message of each section, and trace God's promise of a deliverer from Genesis to Malachi. Every lesson includes a reading assignment, a video lesson script, a check quiz, and unit work in writing and discussion. The course ends with a final assessment and a final exam. Excellence, Faith, Purpose.$j$)
on conflict (slug) do nothing;

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'bib-101';
  if cid is null then raise exception 'Run unit 1 first'; end if;
end
$seed$;
